package com.powerliq.valuation;
import static org.assertj.core.api.Assertions.*;import com.powerliq.api.contracts.ServiceException;import com.powerliq.financial.PositionSide;import com.powerliq.valuation.ValuationModels.*;import java.math.BigDecimal;import java.time.*;import java.util.*;import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.test.context.*;import org.testcontainers.containers.PostgreSQLContainer;import org.testcontainers.junit.jupiter.*;
@SpringBootTest @Testcontainers class ValuationServiceIntegrationTest{
 @Container static final PostgreSQLContainer<?> POSTGRES=new PostgreSQLContainer<>("postgres:16-alpine");@DynamicPropertySource static void db(DynamicPropertyRegistry r){r.add("spring.datasource.url",POSTGRES::getJdbcUrl);r.add("spring.datasource.username",POSTGRES::getUsername);r.add("spring.datasource.password",POSTGRES::getPassword);}
 @Autowired ValuationApplicationService service;@Autowired JdbcTemplate jdbc;UUID portfolio=UUID.randomUUID();LocalDate date=LocalDate.of(2026,1,2);Instant now=Instant.parse("2026-01-01T12:00:00Z");
 @BeforeEach void clean(){jdbc.update("DELETE FROM valuations");}
 @Test void calculatesPersistsAndReplaysIdempotently(){Request request=request("60");Result first=service.calculate("value-once",request);Result retry=service.calculate("value-once",request);assertThat(retry.id()).isEqualTo(first.id());assertThat(first.portfolioMtmGbp()).isEqualByComparingTo("100");assertThat(first.estimatedCollateralGbp()).isEqualByComparingTo("0");assertThat(service.find(first.id())).isEqualTo(first);assertThat(jdbc.queryForObject("SELECT count(*) FROM valuations",Long.class)).isEqualTo(1);}
 @Test void rejectsIdempotencyConflictAndIncompleteMarketData(){service.calculate("conflict",request("60"));assertThatThrownBy(()->service.calculate("conflict",request("61"))).isInstanceOf(ServiceException.class).extracting(e->((ServiceException)e).descriptor().code()).isEqualTo("IDEMPOTENCY_CONFLICT");Request missing=new Request(portfolio,now,request("60").positions(),List.of());assertThatThrownBy(()->service.calculate("missing",missing)).isInstanceOf(ServiceException.class).extracting(e->((ServiceException)e).descriptor().code()).isEqualTo("MARKET_DATA_INCOMPLETE");assertThat(jdbc.queryForObject("SELECT count(*) FROM valuations",Long.class)).isEqualTo(1);}
 private Request request(String market){var p=new PositionInput(UUID.fromString("00000000-0000-0000-0000-000000000010"),portfolio,PositionSide.LONG,new BigDecimal("50"),new BigDecimal("10"),date,1,now);var price=new PriceInput("N2EX",date,1,new BigDecimal(market),now,now);return new Request(portfolio,now,List.of(p),List.of(price));}
}
